package com.bank.portal.web; import com.bank.portal.service.BankingService; import com.bank.portal.web.ApiDtos.*; import jakarta.validation.Valid; import java.util.*; import lombok.RequiredArgsConstructor; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/customers") @RequiredArgsConstructor @PreAuthorize("hasRole('STAFF')") public class CustomerController {private final BankingService service; @GetMapping public List<CustomerView> all(){return service.customerList();} @GetMapping("/{id}") public CustomerView one(@PathVariable Long id){return service.customerView(id);}@PostMapping public CustomerView create(@Valid @RequestBody CustomerRequest r){return service.createCustomer(r);}@PutMapping("/{id}") public CustomerView update(@PathVariable Long id,@Valid @RequestBody CustomerRequest r){return service.updateCustomer(id,r);}@DeleteMapping("/{id}") public void delete(@PathVariable Long id){service.deleteCustomer(id);}}
